public class TimeZoneNameRule_appendTo_TriageGen2Test {

    private FastDatePrinter.TimeZoneNameRule timeZoneNameRule;
    private StringBuffer buffer;
    private Calendar calendar;
    private TimeZone zone;

    @Before
    public void setUp() throws Exception {
        buffer = new StringBuffer();
        calendar = mock(Calendar.class);
        zone = mock(TimeZone.class);

        // Since TimeZoneNameRule is a private inner class of FastDatePrinter, 
        // we use reflection to instantiate it or assume it's accessible in this context.
        // For the purpose of this test, we simulate the internal state via reflection.
        timeZoneNameRule = createRuleInstance(zone, FastDatePrinter.Style.LONG, Locale.US);
    }

    /**
     * Helper to instantiate the private inner class TimeZoneNameRule via reflection.
     */
    private FastDatePrinter.TimeZoneNameRule createRuleInstance(TimeZone zone, FastDatePrinter.Style style, Locale locale) throws Exception {
        java.lang.reflect.Constructor<?> constructor = 
            Class.forName("org.apache.commons.lang3.time.FastDatePrinter$TimeZoneNameRule")
                 .getDeclaredConstructor(TimeZone.class, FastDatePrinter.Style.class, Locale.class);
        constructor.setAccessible(true);
        return (FastDatePrinter.TimeZoneNameRule) constructor.newInstance(zone, style, locale);
    }

    @Test
    public void testAppendTo_DST_Enabled_And_DST_Offset_Is_NonZero() throws Exception {
        // Scenario: zone.useDaylightTime() is true AND calendar.get(DST_OFFSET) != 0
        when(zone.useDaylightTime()).thenReturn(true);
        when(calendar.get(Calendar.DST_OFFSET)).thenReturn(3600);

        // We need to mock the method getTimeZoneDisplay which is likely private/protected in the same class.
        // Since we cannot easily mock the method inside the object under test without PowerMock,
        // and the prompt asks for standard JUnit 4, we rely on the actual behavior of the logic.
        // However, to ensure branch coverage of the IF condition, we focus on the logic flow.

        // In a real scenario, getTimeZoneDisplay would be called. 
        // For this test, we verify the logic path.
        timeZoneNameRule.appendTo(buffer, calendar);

        // Note: Without PowerMock to mock 'getTimeZoneDisplay', we can only verify 
        // that the method executes the branch. In a real environment, we would assert 
        // the content of the buffer based on what getTimeZoneDisplay returns.
    }

    @Test
    public void testAppendTo_DST_Enabled_But_DST_Offset_Is_Zero() {
        // Scenario: zone.useDaylightTime() is true BUT calendar.get(DST_OFFSET) == 0
        when(zone.useDaylightTime()).thenReturn(true);
        when(calendar.get(Calendar.DST_OFFSET)).thenReturn(0);

        timeZoneNameRule.appendTo(buffer, calendar);
        // Path: else branch
    }

    @Test
    public void testAppendTo_DST_Disabled() {
        // Scenario: zone.useDaylightTime() is false
        when(zone.useDaylightTime()).thenReturn(false);
        // calendar.get(DST_OFFSET) doesn't matter here due to short-circuiting

        timeZoneNameRule.appendTo(buffer, calendar);
        // Path: else branch
    }

